import { test, expect } from '@playwright/test';
for (const width of [390, 1440]) {
  test('framework viewport ' + width, async ({ page }) => {
    const external: string[] = [];
    await page.route('**/*', async route => {
      if (route.request().url().startsWith('http://127.0.0.1:3187/')) await route.continue();
      else { external.push(route.request().url()); await route.abort(); }
    });
    await page.setViewportSize({ width, height: 844 });
    const response = await page.goto('/');
    expect(response?.status()).toBe(200);
    await expect(page.getByRole('heading', { name: 'Framework environment only' })).toBeVisible();
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
    expect(response?.headers()['content-security-policy']).toContain("connect-src 'self'");
    expect(external).toEqual([]);
  });
}
